import { generateKeyPairSync, randomUUID } from 'node:crypto';

const { privateKey, publicKey } = generateKeyPairSync('ed25519', {
  privateKeyEncoding: { type: 'pkcs8', format: 'pem' },
  publicKeyEncoding: { type: 'spki', format: 'pem' },
});

const b64 = (pem) => Buffer.from(pem).toString('base64');

process.stdout.write(
  [
    '',
    '# Access-token signing (Ed25519). Generated by tools/scripts/generate-jwt-keys.mjs',
    `AUTH_JWT_KID=${randomUUID()}`,
    `AUTH_JWT_PRIVATE_KEY=${b64(privateKey)}`,
    `AUTH_JWT_PUBLIC_KEY=${b64(publicKey)}`,
    '',
  ].join('\n'),
);
